// Credit bureau reporting (transmission) abstraction. The Metro 2 file is
// generated by metro2.ts; THIS module is the single swap-point for delivering
// that file to Equifax, Experian, and TransUnion (typically via SFTP).
//
// The default implementation is a mock that records the file but performs no
// network transmission. To go live, implement an SFTP-backed provider here and
// register it with setReportingProvider(). Routes must never open an SFTP
// connection directly.

export type Bureau = "equifax" | "experian" | "transunion";

export interface TransmissionResult {
  bureau: Bureau | "all";
  transmitted: boolean;
  ref: string;
  notes?: string;
}

export interface ReportingProvider {
  readonly name: string;
  transmit(periodKey: string, content: string): Promise<TransmissionResult>;
}

class MockReportingProvider implements ReportingProvider {
  readonly name = "mock";

  async transmit(periodKey: string, content: string): Promise<TransmissionResult> {
    // No network egress. Real implementation would SFTP-upload `content` to each
    // bureau's inbound directory using credentials from environment/secrets.
    console.log(
      `[reporting:mock] Would transmit Metro 2 file for ${periodKey} (${content.length} bytes) to Equifax/Experian/TransUnion.`,
    );
    return {
      bureau: "all",
      transmitted: false,
      ref: `mock_transmit_${periodKey}_${Date.now()}`,
      notes: "Mock provider: file generated and stored, not transmitted. Configure a live SFTP provider to send to bureaus.",
    };
  }
}

let provider: ReportingProvider = new MockReportingProvider();

export function getReportingProvider(): ReportingProvider {
  return provider;
}

export function setReportingProvider(next: ReportingProvider): void {
  provider = next;
}

export { MockReportingProvider };
